<template>
<div class="design" :class="{dark,collapsed}">
<aside><a class="brand" href="/design-preview"><b>▱</b><span v-if="!collapsed">Personal-Bench<small>个人测试工作台</small></span></a><button class="search-button" @click="openSearch">⌕ <span v-if="!collapsed">搜索工具 <kbd>Ctrl K</kbd></span></button><nav><button class="nav-item" :class="{active:!selected}" @click="navigate(null)" title="工作台"><PreviewIcon name="dashboard" /> <span v-if="!collapsed">工作台</span></button><section v-for="group in groups" :key="group.name"><button class="group" @click="toggleFold(group.name)" :aria-expanded="!folded.includes(group.name)">{{ collapsed ? '···' : group.name }}<span v-if="!collapsed">{{folded.includes(group.name)?'+':'−'}}</span></button><template v-if="collapsed || !folded.includes(group.name)"><div v-for="tool in group.items" :key="tool.path" class="nav-row"><button class="nav-item" :class="{active:selected?.path===tool.path}" @click="navigate(tool)" :title="tool.name"><PreviewIcon :name="tool.path" /><span v-if="!collapsed">{{tool.name}}</span></button></div></template></section></nav><footer><button @click="dark=!dark" :title="dark?'浅色外观':'深色外观'"><PreviewIcon name="theme" /> <span v-if="!collapsed">{{dark?'浅色外观':'深色外观'}}</span></button><button @click="collapsed=!collapsed" :title="collapsed?'展开导航':'收起导航'"><PreviewIcon :name="collapsed ? 'expand' : 'collapse'" /> <span v-if="!collapsed">收起导航</span></button><p v-if="!collapsed">ME <span>我的工作空间<small>LOCAL WORKSPACE</small></span><em>●</em></p></footer></aside>
<main><header><span>工作空间 / {{selected?.name || '工作台'}}</span><span class="badge">新版工作空间</span><button @click="emit('switch-legacy')">切换旧版界面 ↗</button></header><div v-if="$slots.default" class="business-page" :data-page="route.path">
  <div class="module-heading"><div><span class="module-eyebrow">{{ moduleInfo.category }}</span><h1>{{ selected?.name || moduleInfo.title }}</h1><p>{{ moduleInfo.description }}</p></div><span class="module-index">{{ moduleInfo.code }}</span></div>
  <div class="module-body"><slot /></div>
</div><template v-else><div class="heading"><p>YOUR PERSONAL COMMAND CENTER</p><h1>{{selected?.name || '让工作，井然有序。'}}</h1><span>测试、调试与知识，在一个专注的空间里。</span></div><div v-if="selected" class="destination"><div><h2>{{selected.name}}</h2><p>{{selected.desc}}</p></div><RouterLink :to="selected.path">打开工具 ↗</RouterLink><button @click="navigate(null)">返回总览</button></div><div class="dashboard"><section><div class="title"><h2>常用工具 <small>TOOLS</small></h2><button @click="openSearch">全部工具 ↗</button></div><button class="hero" @click="navigate(tools[0])"><span>01 / DEVICE LAB</span><div class="phone" aria-hidden="true"><svg class="android" viewBox="0 0 48 54"><g fill="currentColor"><path d="M10 19a14 14 0 0 1 28 0Z"/><rect x="10" y="22" width="28" height="21" rx="3"/><rect x="3" y="22" width="5" height="19" rx="2.5"/><rect x="40" y="22" width="5" height="19" rx="2.5"/><rect x="15" y="39" width="6" height="13" rx="3"/><rect x="27" y="39" width="6" height="13" rx="3"/></g><path d="m14 7-4-6m24 6 4-6" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><g fill="var(--bg)"><circle cx="18" cy="13" r="1.5"/><circle cx="30" cy="13" r="1.5"/></g></svg></div><h3>ADB 工具</h3><p>连接设备，掌控每一次调试。</p><strong>进入工作区 ↗</strong></button><div class="tiles"><button v-for="tool in tools.slice(1,3)" :key="tool.path" @click="navigate(tool)"><PreviewIcon :name="tool.path" /><span><b>{{tool.name}}</b><small>{{tool.desc}}</small></span><em>↗</em></button></div></section><section class="panel"><div class="title"><h2>测试概览 <small>OVERVIEW</small></h2><span>示意数据</span></div><div class="counts"><div v-for="metric in metrics" :key="metric[0]"><span>{{metric[0]}}</span><strong>{{countUp(metric[1])}}</strong></div></div><div v-for="rate in rates" :key="rate[0]" class="rate"><span>{{rate[0]}}<b>{{countUp(rate[1])}}%</b></span><div><i :style="{width:countUp(rate[1])+'%'}"></i></div></div><p class="note">仅作视觉示意，打开工具使用真实数据。</p></section></div><section class="panel execution"><div class="title"><h2>执行状态 <small>EXECUTION</small></h2><span>示意数据 · {{countUp(128)}} 条用例</span></div><div class="statuses"><button v-for="status in statuses" :key="status.name" :class="{chosen:filter===status.name}" @click="filter=filter===status.name?'':status.name"><i :style="{background:status.color}"></i>{{status.name}}<b>{{countUp(status.count)}}</b></button></div><div class="distribution"><i v-for="status in statuses" :key="status.name" :style="{flex:status.count,background:status.color,opacity:!filter || filter===status.name?1:.15}"></i></div><div class="note feedback" aria-live="polite"><span>{{filter?'已聚焦：'+filter+'；再次点击恢复全部':'点击状态聚焦分布'}}</span><RouterLink to="/executions">查看真实执行记录 ↗</RouterLink></div></section><div class="endnote">PERSONAL-BENCH / DESIGN STUDY 01 <span>冷白 · 钛银 · 专注</span></div></template></main>
<dialog ref="dialog" @click="backdrop" @close="query=''" aria-label="搜索工具"><div class="search-head"><span>⌕</span><input ref="input" v-model="query" placeholder="搜索工具、页面…" aria-label="搜索工具" @keydown.down.prevent="move(1)" @keydown.up.prevent="move(-1)" @keydown.enter.prevent="choose"/><button @click="dialog.close()">Esc</button></div><p class="search-tip">快速前往 <span>↑ ↓ 选择 · Enter 打开</span></p><div class="results"><button v-for="(tool,index) in results" :key="tool.path" :class="{highlighted:index===highlighted}" @mousemove="highlighted=index" @click="navigate(tool);dialog.close()"><PreviewIcon :name="tool.path" /><span>{{tool.name}}<small>{{tool.desc}}</small></span><em>↵</em></button><p v-if="!results.length">未找到相关工具，试试“接口”或“用例”。</p></div></dialog>
</div>
</template>
<script setup>
import { useRouter, useRoute } from 'vue-router'
import '../styles/workspace-v2.css'
import PreviewIcon from '../components/PreviewIcon.vue'

import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue'
const props=defineProps({integrated:Boolean,menuGroups:{type:Array,default:()=>[]}})
const emit=defineEmits(['switch-legacy'])
const router=useRouter(), route=useRoute()
function navigate(tool){
 if(dialog.value?.open)dialog.value.close()
 if(props.integrated)router.push(tool ? tool.path : '/design-preview');else selected.value=tool
}
const tools=[{name:'ADB 工具',path:'/adbtools',desc:'设备调试与日志分析',group:'测试工具'},{name:'接口测试',path:'/apitest',desc:'请求调试与接口验证',group:'测试工具'},{name:'测试数据工厂',path:'/test-data',desc:'快速构造测试素材',group:'测试工具'},{name:'需求管理',path:'/requirements',desc:'需求文档与覆盖关系',group:'测试管理'},{name:'测试用例',path:'/cases',desc:'编写与维护测试用例',group:'测试管理'},{name:'测试执行',path:'/executions',desc:'执行任务与结果记录',group:'测试管理'},{name:'缺陷跟踪',path:'/bugs',desc:'问题跟踪与闭环处理',group:'测试管理'},{name:'知识库',path:'/knowledge',desc:'沉淀经验与知识',group:'资产与知识'},{name:'AI 模型配置',path:'/ai',desc:'模型与提示词配置',group:'资产与知识'}]

const moduleDetails={
 '/adbtools':['DEVICE LAB','设备调试','连接设备，查看日志，完成调试与验证。','01'],
 '/apitest':['API STUDIO','接口测试工具','在专注的请求工作区中调试、验证与管理接口。','02'],
 '/test-data':['DATA FACTORY','测试数据工厂','按需构造测试素材，清晰掌握生成任务与结果。','03'],
 '/requirements':['REQUIREMENTS','需求 PRD','组织需求文档，建立需求与测试覆盖的联系。','04'],
 '/cases':['TEST CASES','测试用例','维护测试步骤与预期结果，让验证过程可复用。','05'],
 '/executions':['EXECUTION','测试执行','推进执行任务，记录结果，跟进异常。','06'],
 '/bugs':['ISSUE TRACKER','缺陷跟踪','从发现到关闭，追踪每一个问题的处理过程。','07'],
 '/projects':['PROJECTS','项目管理','管理项目范围，为测试资产建立清晰归属。','08'],
 '/report':['QUALITY INSIGHTS','质量报表','查看执行、覆盖与缺陷分布，掌握质量状况。','09'],
 '/automation':['AUTOMATION','自动化脚本','组织自动化脚本，管理调度与执行。','10'],
 '/releases':['RELEASES','版本与环境','保持被测版本与测试环境的信息一致。','11'],
 '/tracking':['EVENT INSPECTOR','埋点监控','检查事件与参数，分析采集结果。','12'],
 '/notification-monitor':['NOTIFICATION LAB','通知监控','查看通知记录，核对推送与接收表现。','13'],
 '/jmeter':['PERFORMANCE LAB','性能测试','配置测试场景，查看执行进度与性能结果。','14'],
 '/mysql-query':['DATABASE STUDIO','数据库查询','连接数据源，在只读工作区中探索与验证数据。','15'],
 '/knowledge':['KNOWLEDGE','知识库','整理文档、经验与资料，积累可复用知识。','16'],
 '/skills':['SKILL LIBRARY','SKILL 管理','管理技能资产与编排配置。','17'],
 '/ai':['MODEL SETTINGS','AI 模型配置','集中管理模型供应商、参数与提示词。','18'],
 '/menu-manage':['WORKSPACE SETTINGS','菜单管理','调整工作空间的导航名称、分组与顺序。','19']
}
const moduleInfo=computed(()=>{const [category,title,description,code]=moduleDetails[route.path] || ['WORKSPACE',selected.value?.name || '工作空间','', ''];return {category,title,description,code}})

function stored(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return Array.isArray(value)?value.filter(v=>typeof v==='string'):fallback}catch{return fallback}}
const folded=ref(stored('twb_preview_folded',[])),collapsed=ref(localStorage.getItem('twb_preview_collapsed')==='1'),dark=ref(localStorage.getItem('twb_preview_dark')==='1'),selected=ref(null),filter=ref('')
// Both layouts receive the same backend-configured groups from App.vue.
const groups=computed(()=>props.menuGroups.length ? props.menuGroups : ['测试工具','测试管理','资产与知识'].map(name=>({name,items:tools.filter(t=>t.group===name)})))
const allTools=computed(()=>groups.value.flatMap(group=>group.items.map(item=>({...item,desc:tools.find(t=>t.path===item.path)?.desc || group.name}))))
watch(folded,v=>localStorage.setItem('twb_preview_folded',JSON.stringify(v)),{deep:true});watch(collapsed,v=>localStorage.setItem('twb_preview_collapsed',v?'1':'0'));watch(dark,v=>localStorage.setItem('twb_preview_dark',v?'1':'0'))
function toggleFold(name){folded.value=folded.value.includes(name)?folded.value.filter(n=>n!==name):[...folded.value,name]}
const metrics=[['需求',24],['用例',128],['缺陷',16],['未关闭',5]],rates=[['执行率',82],['通过率',96],['需求覆盖率',90]],statuses=[{name:'通过',count:96,color:'#4f968c'},{name:'失败',count:8,color:'#bc655e'},{name:'阻塞',count:5,color:'#b78e45'},{name:'跳过',count:6,color:'#6b8faa'},{name:'未执行',count:13,color:'#b2bdc8'}]
const dialog=ref(null),input=ref(null),query=ref(''),highlighted=ref(0),results=computed(()=>allTools.value.filter(t=>(t.name+' '+t.desc+' '+t.path).toLowerCase().includes(query.value.trim().toLowerCase())))
watch(query,()=>highlighted.value=0)
async function openSearch(){if(dialog.value.open)return;dialog.value.showModal();await nextTick();input.value.focus()}
function move(step){if(results.value.length)highlighted.value=(highlighted.value+step+results.value.length)%results.value.length}
function choose(){const tool=results.value[highlighted.value];if(tool){navigate(tool);dialog.value.close()}}
function backdrop(e){if(e.target!==dialog.value)return;const r=dialog.value.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.value.close()}
function shortcut(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}}
const progress=ref(0)
let animation=0
function countUp(value){return Math.round(value*progress.value)}
function animateMetrics(){
 cancelAnimationFrame(animation)
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){progress.value=1;return}
 progress.value=0
 const start=performance.now()
 function frame(now){const t=Math.min((now-start)/1100,1);progress.value=1-Math.pow(1-t,3);if(t<1)animation=requestAnimationFrame(frame)}
 animation=requestAnimationFrame(frame)
}
watch(selected,animateMetrics)
watch([() => route.path, allTools], () => {if(props.integrated)selected.value=allTools.value.find(t=>t.path===route.path)||null; const current=groups.value.find(g=>g.items.some(t=>t.path===route.path));if(current)folded.value=folded.value.filter(n=>n!==current.name);animateMetrics()},{immediate:true})
function onVisible(){if(!document.hidden)animateMetrics()}
onMounted(()=>{window.addEventListener('keydown',shortcut);document.addEventListener('visibilitychange',onVisible);animateMetrics()})
onUnmounted(()=>{window.removeEventListener('keydown',shortcut);document.removeEventListener('visibilitychange',onVisible);cancelAnimationFrame(animation)})
</script>
