hover);color:var(--accent)!important;box-shadow:inset 2px 0 var(--accent);font-weight:600}.nav-item:hover,.nav-row:hover,.search-button:hover{background:var(--hover)}.group{display:flex;justify-content:space-between;width:100%;font-size:10px!important;letter-spacing:1px;color:var(--muted)!important;padding:24px 12px 9px!important}footer{border-top:1px solid var(--line);margin-top:12px;padding-top:10px}footer>button{width:100%;padding:10px 12px!important;border-radius:7px}footer>button:hover{background:var(--hover)}footer>button span{margin-left:12px;color:var(--muted)}footer p{display:flex;gap:12px;align-items:center;border-top:1px solid var(--line);padding:20px 6px 0;font-size:11px;color:var(--accent)}footer small{display:block;font-size:8px;color:var(--muted);letter-spacing:1px;margin-top:5px}footer em{margin-left:auto;color:#739e91;font-style:normal;font-size:8px}main{overflow:auto;min-width:0;padding:0 44px 24px;background:radial-gradient(ellipse at 80% 0%,#a4b7cc12,transparent 60%)}header{height:68px;display:flex;align-items:center;gap:20px;border-bottom:1px solid var(--line);font-size:11px;color:var(--muted)}.badge{margin-left:auto;border:1px solid var(--line);padding:5px 10px;border-radius:20px;font-size:10px}.heading{margin:42px 0 30px}.heading>p{font-size:9px;letter-spacing:2.5px;color:var(--accent);margin-bottom:12px}.heading h1{font-size:32px;letter-spacing:-1px;margin:0 0 12px;font-weight:600}.heading>span{font-size:13px;color:var(--muted)}.dashboard{display:grid;grid-template-columns:1.5fr 1fr;gap:26px}.title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:18px}.title h2{font-size:15px;font-weight:600;margin:0}.title small{font-size:8px;letter-spacing:1px;color:var(--muted);font-weight:400;margin-left:7px}.title>span,.title button{font-size:10px;color:var(--muted)}.hero{display:block;position:relative;overflow:hidden;min-height:235px;width:100%;background:linear-gradient(115deg,var(--surface),var(--hover))!important;