/* Cold titanium surfaces and consistent interaction rhythm. */
.design{--accent:#396781;--muted:#617486;--line:#d9e3eb;--hover:#e6eef4}
.design.dark{--accent:#93bdd5;--muted:#a5b6c6;--line:#304354;--hover:#243a4c}
aside{background:linear-gradient(160deg,var(--surface),var(--bg));padding-top:24px}
.brand{padding-bottom:24px}.brand b{transform:rotate(-8deg)}
.nav-item{min-height:44px;position:relative;font-size:13px!important;transition:background .18s,color .18s,box-shadow .18s}
.nav-item :deep(svg){opacity:.8;transition:opacity .18s,transform .18s}.nav-item:hover :deep(svg){opacity:1;transform:translateY(-1px)}
.nav-item.active{box-shadow:inset 3px 0 var(--accent),0 2px 6px #223f5a06;background:linear-gradient(90deg,var(--hover),transparent)}
.nav-row{margin:3px 0}.group{padding-top:20px!important;font-weight:600;min-height:44px}.group:hover{color:var(--accent)!important}
header{position:sticky;top:0;z-index:5;background:var(--bg)}header>button{padding:8px 12px!important;border:1px solid var(--line)!important;border-radius:7px}header>button:hover{background:var(--hover)}
.heading{padding-left:1px}.hero{border-radius:16px;box-shadow:0 4px 20px #39597606}.hero:hover .phone{transform:rotate(6deg) translateY(-4px)}.phone{transition:transform .35s cubic-bezier(.2,.7,.3,1)}
.tiles button{min-height:82px}.tiles button:hover{box-shadow:0 4px 12px #274a6610}.panel{box-shadow:0 3px 14px #274a6605;border-radius:14px}
.search-button:hover{border-color:var(--accent)!important}.search-button:active,.tiles button:active,.hero:active{box-shadow:inset 0 1px 5px #274a6618}
.business-page{animation:page-enter .24s ease-out}.business-page :deep(.card){border-radius:12px;box-shadow:0 3px 14px #274a6606}.business-page :deep(h1){letter-spacing:-.6px}
.statuses button{min-height:44px}.counts strong{letter-spacing:-1px}.results button{min-height:58px}.results button.highlighted{box-shadow:inset 2px 0 var(--accent)}
@keyframes page-enter{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){.business-page{animation:none}.design *{transition:none!important}}
